DROP POLICY IF EXISTS "company_assets_update" ON storage.objects;
CREATE POLICY "company_assets_update" ON storage.objects
    FOR UPDATE USING (
        bucket_id = 'company-assets'
        AND (storage.foldername(name))[1] = public.user_company_id()::TEXT
    );

