-- ============================================================
-- 7. NOTIFICATION TRIGGER: low-stock alerts
-- ============================================================
CREATE OR REPLACE FUNCTION public.notify_low_stock()
RETURNS TRIGGER AS $$
DECLARE
    v_company_id UUID;
    v_product_name TEXT;
    v_current NUMERIC;
    v_low_level INT;
BEGIN
    IF NEW.current_stock >= 0 THEN
        RETURN NEW;
    END IF;

    SELECT p.company_id, p.name, p.low_stock_level
    INTO v_company_id, v_product_name, v_low_level
    FROM products p WHERE p.id = NEW.product_id;

    IF v_company_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT COALESCE(SUM(ps.current_stock), 0)
    INTO v_current
    FROM product_stock ps WHERE ps.product_id = NEW.product_id;

    IF v_current <= v_low_level THEN
        INSERT INTO notifications (company_id, user_id, title, message, type, link)
        SELECT
            v_company_id,
            pr.id,
            'Low stock: ' || v_product_name,
            'Stock level is ' || v_current || ' (reorder at ' || v_low_level || ')',
            'warning',
            '/stock/low-stock'
        FROM profiles pr
        WHERE pr.company_id = v_company_id AND pr.is_active = true
        LIMIT 20;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

DROP TRIGGER IF EXISTS on_low_stock_notify ON product_stock;
CREATE TRIGGER on_low_stock_notify
    AFTER UPDATE ON product_stock
    FOR EACH ROW EXECUTE FUNCTION public.notify_low_stock();

-- ==================================================================
-- from 006_atomic_posting.sql
-- ==================================================================
-- ============================================================
-- 006_atomic_posting.sql – Atomic RPCs for document posting
--
-- The TypeScript service previously posted stock line-by-line
-- with a non-atomic read-modify-write, wrote the literal string
-- 'default' into a UUID column, and discarded the error. That
-- meant posting either silently did nothing or left stock and
-- its movement ledger out of sync. These RPCs do the whole
-- operation inside one database transaction, so it either fully
-- applies or fully rolls back.
-- ============================================================

-- ============================================================
-- 1. post_document_stock
--    Applies stock movements for every line of a document and
--    sets the document status, atomically.
-- ============================================================
CREATE OR REPLACE FUNCTION post_document_stock(p_transaction_id UUID)
RETURNS VOID AS $$
DECLARE
    v_txn transactions%ROWTYPE;
    v_item RECORD;
    v_warehouse_id UUID;
    v_current NUMERIC;
    v_new NUMERIC;
    v_qty_change NUMERIC;
    v_movement_type TEXT;
    v_user_id UUID := auth.uid();
BEGIN
    SELECT * INTO v_txn FROM transactions WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transaction not found: %', p_transaction_id;
    END IF;

    IF v_txn.status = 'cancelled' THEN
        RAISE EXCEPTION 'Cannot post a cancelled transaction';
    END IF;

    IF v_txn.status IN ('confirmed', 'paid', 'partial') THEN
        RAISE EXCEPTION 'Transaction is already posted';
    END IF;

    -- Quotations and purchase orders do not move stock
    IF v_txn.type NOT IN ('sale', 'purchase') THEN
        UPDATE transactions
        SET status = 'confirmed', updated_at = now()
        WHERE id = p_transaction_id;
        RETURN;
    END IF;

    -- Resolve warehouse: document's own, else the company's first active one
    v_warehouse_id := v_txn.warehouse_id;

    IF v_warehouse_id IS NULL THEN
        SELECT w.id INTO v_warehouse_id
        FROM warehouses w
        WHERE w.company_id = v_txn.company_id AND w.is_active = true
        ORDER BY w.created_at ASC
        LIMIT 1;
    END IF;

    IF v_warehouse_id IS NULL THEN
        RAISE EXCEPTION 'No active warehouse found. Create one in Settings first.';
    END IF;

    FOR v_item IN
        SELECT * FROM transaction_items
        WHERE transaction_id = p_transaction_id AND product_id IS NOT NULL
        ORDER BY sort_order
    LOOP
        -- Lock the existing stock row, then read it. `FOR UPDATE` is illegal
        -- on an aggregate query, so the lock and the read must be separate.
        v_current := 0;
        SELECT current_stock INTO v_current
        FROM product_stock
        WHERE product_id = v_item.product_id AND warehouse_id = v_warehouse_id
        FOR UPDATE;

        IF v_txn.type = 'sale' THEN
            v_qty_change := -v_item.quantity;
            v_movement_type := 'sales';
        ELSE
            v_qty_change := v_item.quantity;
            v_movement_type := 'purchase';
        END IF;

        v_new := v_current + v_qty_change;

        IF v_new < 0 THEN
            RAISE EXCEPTION 'Insufficient stock for %: available %, required %',
                v_item.product_name, v_current, v_item.quantity;
        END IF;

        INSERT INTO product_stock (product_id, warehouse_id, current_stock, avg_cost, last_updated)
        VALUES (v_item.product_id, v_warehouse_id, v_new, v_item.rate, now())
        ON CONFLICT (product_id, warehouse_id) DO UPDATE
        SET current_stock = v_new,
            -- Weighted-average cost on inbound, unchanged on outbound
            avg_cost = CASE
                WHEN v_qty_change > 0 AND v_current + v_qty_change > 0
                THEN ((product_stock.avg_cost * product_stock.current_stock)
                      + (v_item.rate * v_qty_change))
                     / (product_stock.current_stock + v_qty_change)
                ELSE product_stock.avg_cost
            END,
            last_updated = now();

        INSERT INTO stock_movements (
            company_id, product_id, warehouse_id, type,
            reference_type, reference_id,
            quantity, balance_after, unit_cost, total_value, notes, created_by
        ) VALUES (
            v_txn.company_id, v_item.product_id, v_warehouse_id, v_movement_type,
            'transaction', p_transaction_id,
            v_qty_change, v_new, v_item.rate, v_item.total_amount,
            v_txn.type || ' - ' || v_txn.document_number, v_user_id
        );
    END LOOP;

    -- Ledger entry so the party account reflects the document
    IF v_txn.type = 'sale' AND v_txn.customer_id IS NOT NULL THEN
        INSERT INTO customer_ledger (
            customer_id, date, description, debit, credit, reference_type, reference_id
        ) VALUES (
            v_txn.customer_id, v_txn.document_date,
            'Sale: ' || v_txn.document_number,
            v_txn.grand_total, 0, 'transaction', p_transaction_id
        );
    ELSIF v_txn.type = 'purchase' AND v_txn.supplier_id IS NOT NULL THEN
        INSERT INTO supplier_ledger (
            supplier_id, date, description, debit, credit, reference_type, reference_id
        ) VALUES (
            v_txn.supplier_id, v_txn.document_date,
            'Purchase: ' || v_txn.document_number,
            0, v_txn.grand_total, 'transaction', p_transaction_id
        );
    END IF;

    UPDATE transactions
    SET status = CASE
            WHEN amount_paid >= grand_total AND grand_total > 0 THEN 'paid'
            WHEN amount_paid > 0 THEN 'partial'
            ELSE 'confirmed'
        END,
        warehouse_id = v_warehouse_id,
        updated_at = now()
    WHERE id = p_transaction_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 2. cancel_document_stock
--    Reverses a posted document's stock and ledger effects.
-- ============================================================
CREATE OR REPLACE FUNCTION cancel_document_stock(p_transaction_id UUID)
RETURNS VOID AS $$
DECLARE
    v_txn transactions%ROWTYPE;
    v_item RECORD;
    v_warehouse_id UUID;
    v_current NUMERIC;
    v_new NUMERIC;
    v_qty_change NUMERIC;
    v_movement_type TEXT;
    v_user_id UUID := auth.uid();
BEGIN
    SELECT * INTO v_txn FROM transactions WHERE id = p_transaction_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transaction not found: %', p_transaction_id;
    END IF;

    IF v_txn.status = 'cancelled' THEN
        RAISE EXCEPTION 'Transaction is already cancelled';
    END IF;

    IF v_txn.status NOT IN ('confirmed', 'paid', 'partial') THEN
        UPDATE transactions SET status = 'cancelled', updated_at = now()
        WHERE id = p_transaction_id;
        RETURN;
    END IF;

    IF v_txn.type IN ('sale', 'purchase') THEN
        v_warehouse_id := v_txn.warehouse_id;

        IF v_warehouse_id IS NULL THEN
            SELECT w.id INTO v_warehouse_id
            FROM warehouses w
            WHERE w.company_id = v_txn.company_id AND w.is_active = true
            ORDER BY w.created_at ASC LIMIT 1;
        END IF;

        IF v_warehouse_id IS NULL THEN
            UPDATE transactions SET status = 'cancelled', updated_at = now()
            WHERE id = p_transaction_id;
            RETURN;
        END IF;

        FOR v_item IN
            SELECT * FROM transaction_items
            WHERE transaction_id = p_transaction_id AND product_id IS NOT NULL
            ORDER BY sort_order
        LOOP
            -- Lock the existing stock row, then read it. `FOR UPDATE` is
            -- illegal on an aggregate query.
            v_current := 0;
            SELECT current_stock INTO v_current
            FROM product_stock
            WHERE product_id = v_item.product_id AND warehouse_id = v_warehouse_id
            FOR UPDATE;

            -- Undo the original direction
            IF v_txn.type = 'sale' THEN
                v_qty_change := v_item.quantity;
                v_movement_type := 'sales_return';
            ELSE
                v_qty_change := -v_item.quantity;
                v_movement_type := 'purchase_return';
            END IF;

            v_new := v_current + v_qty_change;

            -- Cancelling a purchase removes stock that may already have been
            -- sold. Refuse rather than silently driving the balance negative.
            IF v_new < 0 THEN
                RAISE EXCEPTION
                    'Cannot cancel: reversing % would leave stock of % at %. Stock has already been consumed.',
                    v_txn.document_number, v_item.product_name, v_new;
            END IF;

            INSERT INTO product_stock (product_id, warehouse_id, current_stock, last_updated)
            VALUES (v_item.product_id, v_warehouse_id, v_new, now())
            ON CONFLICT (product_id, warehouse_id) DO UPDATE
            SET current_stock = v_new, last_updated = now();

            INSERT INTO stock_movements (
                company_id, product_id, warehouse_id, type,
                reference_type, reference_id,
                quantity, balance_after, unit_cost, total_value, notes, created_by
            ) VALUES (
                v_txn.company_id, v_item.product_id, v_warehouse_id, v_movement_type,
                'cancellation', p_transaction_id,
                v_qty_change, v_new, v_item.rate, v_item.total_amount,
                'Cancellation of ' || v_txn.document_number, v_user_id
            );
        END LOOP;
    END IF;

    -- Reverse the ledger entry created at posting time
    IF v_txn.type = 'sale' AND v_txn.customer_id IS NOT NULL THEN
        DELETE FROM customer_ledger
        WHERE reference_type = 'transaction' AND reference_id = p_transaction_id;
    ELSIF v_txn.type = 'purchase' AND v_txn.supplier_id IS NOT NULL THEN
        DELETE FROM supplier_ledger
        WHERE reference_type = 'transaction' AND reference_id = p_transaction_id;
    END IF;

    UPDATE transactions SET status = 'cancelled', updated_at = now()
    WHERE id = p_transaction_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 3. apply_document_payment
--    Records a payment and reconciles the linked document in one
--    transaction, so a payment can never be saved without its
--    ledger entry or its invoice status update.
-- ============================================================
CREATE OR REPLACE FUNCTION apply_document_payment(
    p_party_id UUID,
    p_party_type TEXT,
    p_date DATE,
    p_reference_number TEXT,
    p_mode TEXT,
    p_bank_name TEXT,
    p_amount NUMERIC,
    p_notes TEXT,
    p_transaction_id UUID
) RETURNS UUID AS $$
DECLARE
    v_payment_id UUID;
    v_company_id UUID;
    v_txn transactions%ROWTYPE;
    v_user_id UUID := auth.uid();
BEGIN
    IF p_party_type = 'customer' THEN
        SELECT company_id INTO v_company_id FROM customers WHERE id = p_party_id;
        IF v_company_id IS NULL THEN
            RAISE EXCEPTION 'Customer not found';
        END IF;

        INSERT INTO payments_received (
            company_id, customer_id, date, reference_number,
            mode, bank_name, amount, notes, transaction_id, created_by
        ) VALUES (
            v_company_id, p_party_id, p_date, p_reference_number,
            p_mode, p_bank_name, p_amount, p_notes, p_transaction_id, v_user_id
        ) RETURNING id INTO v_payment_id;

        INSERT INTO customer_ledger (
            customer_id, date, description, debit, credit, reference_type, reference_id
        ) VALUES (
            p_party_id, p_date,
            'Payment received' || COALESCE(': ' || p_reference_number, ''),
            0, p_amount, 'payment_received', v_payment_id
        );
    ELSE
        SELECT company_id INTO v_company_id FROM suppliers WHERE id = p_party_id;
        IF v_company_id IS NULL THEN
            RAISE EXCEPTION 'Supplier not found';
        END IF;

        INSERT INTO payments_made (
            company_id, supplier_id, date, reference_number,
            mode, bank_name, amount, notes, transaction_id, created_by
        ) VALUES (
            v_company_id, p_party_id, p_date, p_reference_number,
            p_mode, p_bank_name, p_amount, p_notes, p_transaction_id, v_user_id
        ) RETURNING id INTO v_payment_id;

        INSERT INTO supplier_ledger (
            supplier_id, date, description, debit, credit, reference_type, reference_id
        ) VALUES (
            p_party_id, p_date,
            'Payment made' || COALESCE(': ' || p_reference_number, ''),
            p_amount, 0, 'payment_made', v_payment_id
        );
    END IF;

    IF p_transaction_id IS NOT NULL THEN
        SELECT * INTO v_txn FROM transactions
        WHERE id = p_transaction_id AND company_id = v_company_id FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Document not found for this company';
        END IF;

        IF v_txn.status = 'cancelled' THEN
            RAISE EXCEPTION 'Cannot pay a cancelled document';
        END IF;

        UPDATE transactions
        SET amount_paid = amount_paid + p_amount,
            status = CASE
                WHEN amount_paid + p_amount >= grand_total THEN 'paid'
                WHEN amount_paid + p_amount > 0 THEN 'partial'
                ELSE status
            END,
            updated_at = now()
        WHERE id = p_transaction_id;
    END IF;

    RETURN v_payment_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 4. next_document_number
--    Serialises number allocation so two concurrent saves cannot
--    mint the same document number.
-- ============================================================
CREATE OR REPLACE FUNCTION next_document_number(
    p_company_id UUID,
    p_type TEXT
) RETURNS TEXT AS $$
DECLARE
    v_prefix TEXT;
    v_fy TEXT;
    v_next INT;
    v_lock_key BIGINT;
BEGIN
    v_prefix := CASE p_type
        WHEN 'sale' THEN 'INV'
        WHEN 'purchase' THEN 'PUR'
        WHEN 'quotation' THEN 'QUO'
        WHEN 'purchase_order' THEN 'PO'
        WHEN 'proforma_invoice' THEN 'PI'
        ELSE 'DOC'
    END;

    v_fy := CASE
        WHEN EXTRACT(MONTH FROM CURRENT_DATE) >= 4
            THEN TO_CHAR(CURRENT_DATE, 'YY') || TO_CHAR(CURRENT_DATE + INTERVAL '1 year', 'YY')
        ELSE TO_CHAR(CURRENT_DATE - INTERVAL '1 year', 'YY') || TO_CHAR(CURRENT_DATE, 'YY')
    END;

    -- Advisory lock keyed on company + type
    v_lock_key := ('x' || SUBSTRING(md5(p_company_id::TEXT || p_type), 1, 16))::BIT(64)::BIGINT;
    PERFORM pg_advisory_xact_lock(v_lock_key);

    SELECT COALESCE(MAX(
        CAST(SUBSTRING(document_number FROM '[0-9]+$') AS INT)
    ), 0) + 1
    INTO v_next
    FROM transactions
    WHERE company_id = p_company_id
      AND type = p_type
      AND document_number LIKE v_prefix || '/' || v_fy || '/%';

    RETURN v_prefix || '/' || v_fy || '/' || LPAD(v_next::TEXT, 6, '0');
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 5. GRANTS – the client authenticates as `authenticated`
-- ============================================================
GRANT EXECUTE ON FUNCTION post_document_stock(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION cancel_document_stock(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION apply_document_payment(UUID, TEXT, DATE, TEXT, TEXT, TEXT, NUMERIC, TEXT, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION next_document_number(UUID, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION generate_document_number(TEXT, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION calculate_customer_balance(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION calculate_supplier_balance(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION calculate_product_stock(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION adjust_stock(UUID, UUID, NUMERIC, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_sales_summary(UUID, DATE, DATE) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_purchase_summary(UUID, DATE, DATE) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_stock_summary(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_low_stock(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_fast_moving(UUID, DATE, DATE, INT) TO authenticated;
GRANT EXECUTE ON FUNCTION get_dashboard_customer_outstanding(UUID) TO authenticated;

-- ==================================================================
-- from 007_signup_onboarding.sql
-- ==================================================================
-- ============================================================
-- 007_signup_onboarding.sql – Make self-service signup actually work
--
-- Migration 005 defined public.handle_new_user(), but it could not
-- complete a signup for two independent reasons:
--
--   1. It read the company id from NEW.raw_app_meta_data. Supabase only
--      lets a client write raw_user_meta_data; app_metadata is writable
--      exclusively by the service-role API. So v_company_id was ALWAYS
--      NULL for a self-service signup.
--
--   2. It hard-coded v_role := 'viewer'. Combined with (1), every new
--      account ended up with company_id = NULL, and the very first query
--      in src/lib/tenant.ts threw:
--          "No company is linked to this account"
--      i.e. a freshly provisioned deployment was unusable.
--
-- This migration redefines the trigger so a signup can carry its own
-- company details in raw_user_meta_data (client-writable):
--
--   * company_id supplied and valid  -> join that company as 'viewer'
--   * company_name supplied, no id   -> create a company, user becomes
--                                       its first 'admin' (the owner)
--   * neither supplied               -> unassigned 'viewer', for an
--                                       admin to provision later
--
-- handle_new_company (migration 005) already fires on INSERT INTO
-- companies and provisions the default warehouse, company_settings and
-- system roles, so creating the company here is sufficient.
--
-- Additive only: replaces a function body and re-points one trigger.
-- Does not touch existing rows.
-- ============================================================

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
    v_company_id UUID;
    v_company_name TEXT;
    v_role TEXT := 'viewer';
    v_full_name TEXT;
BEGIN
    -- raw_user_meta_data is the only metadata bucket a browser can set
    -- through supabase.auth.signUp({ options: { data: {...} } }).
    v_company_name := NULLIF(trim(NEW.raw_user_meta_data ->> 'company_name'), '');
    v_full_name := COALESCE(
        NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), ''),
        NULLIF(trim(NEW.raw_user_meta_data ->> 'name'), '')
    );

    -- Optional: attach to an existing company (invite / join flow).
    BEGIN
        v_company_id := NULLIF(trim(NEW.raw_user_meta_data ->> 'company_id'), '')::UUID;
    EXCEPTION WHEN others THEN
        v_company_id := NULL;
    END;

    IF v_company_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM companies WHERE id = v_company_id) THEN
        v_company_id := NULL;
    END IF;

    -- No company given, but a name was: provision a brand new tenant and
    -- make this user its owner. Without this branch the account is stranded.
    IF v_company_id IS NULL AND v_company_name IS NOT NULL THEN
        INSERT INTO companies (name, state, state_code)
        VALUES (
            v_company_name,
            NULLIF(trim(NEW.raw_user_meta_data ->> 'company_state'), ''),
            NULLIF(trim(NEW.raw_user_meta_data ->> 'company_state_code'), '')
        )
        RETURNING id INTO v_company_id;

        -- First user of a company they just created: full admin rights,
        -- otherwise they could not create a single product.
        IF v_company_id IS NOT NULL THEN
            v_role := 'admin';
        END IF;
    END IF;

    INSERT INTO public.profiles (id, company_id, email, full_name, role, is_active)
    VALUES (
        NEW.id,
        v_company_id,
        NEW.email,
        v_full_name,
        v_role,
        true
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Re-point the existing trigger at the updated function body.
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- ------------------------------------------------------------
-- Backfill: any account created under the old trigger is stuck with
-- company_id = NULL and can do nothing. If there is exactly one company
-- in the database, adopt it and promote the oldest unassigned account
-- to admin so an existing deployment is not left broken.
-- ------------------------------------------------------------
DO $$
DECLARE
    v_only_company UUID;
    v_oldest_user UUID;
BEGIN
    SELECT id INTO v_only_company FROM companies ORDER BY created_at ASC LIMIT 1;

    IF v_only_company IS NULL THEN
        RETURN;
    END IF;

    SELECT id INTO v_oldest_user
    FROM profiles
    WHERE company_id IS NULL AND is_active
    ORDER BY created_at ASC
    LIMIT 1;

    IF v_oldest_user IS NOT NULL THEN
        UPDATE profiles
        SET company_id = v_only_company,
            role = 'admin'
        WHERE id = v_oldest_user;
    END IF;
END;
$$;

-- ==================================================================
-- from 008_rbac_backfill.sql
-- ==================================================================
-- ============================================================
-- 8. RBAC BACKFILL FOR EXISTING COMPANIES
--
-- Why this migration exists
-- -----------------------
-- 005_onboarding.sql seeds the `roles` table with a
--     INSERT INTO roles ... FROM companies c CROSS JOIN (VALUES ...)
-- statement. That is correct but it is a one-shot, non-triggered seed: if the
-- `companies` table was still empty when 005 ran, the statement inserted zero
-- rows and nothing ever back-filled them. Because the `WHERE NOT EXISTS` guard
-- only de-duplicates rows that already exist, re-running is safe.
--
-- The live project hit exactly this: `permissions` had 77 rows, but
-- `roles`, `role_permissions` and `user_roles` were all empty. The app still
-- appeared to work because PermissionContext falls back to the hardcoded
-- `getUserPermissions()` map, but the database-driven RBAC path -- the one all
-- the RLS helper functions actually read -- was completely dead.
--
-- Everything below is idempotent: re-running it is a no-op on an already
-- correct database. It is the same logic as 005, re-run at the point where the
-- company rows are guaranteed to exist.
-- ============================================================

-- 8.1 DEFAULT SYSTEM ROLES (one set per company)
INSERT INTO roles (company_id, name, description, is_system)
SELECT c.id, r.name, r.description, true
FROM companies c
CROSS JOIN (VALUES
    ('admin',      'Full access to all modules'),
    ('manager',    'Manages day-to-day operations and inventory'),
    ('accountant', 'Access to finance, ledgers and GST reports'),
    ('viewer',     'Read-only access')
) AS r(name, description)
WHERE NOT EXISTS (
    SELECT 1 FROM roles er WHERE er.company_id = c.id AND er.name = r.name
);

-- 8.2 LINK PROFILES TO THEIR ROLE (profiles.role is a text label; role_permissions
--     is keyed on roles.id, so the two have to be bridged for RLS to work)
INSERT INTO user_roles (user_id, role_id, company_id)
SELECT p.id, r.id, p.company_id
FROM profiles p
JOIN roles r ON r.company_id = p.company_id AND lower(r.name) = lower(p.role)
WHERE p.company_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM user_roles ur WHERE ur.user_id = p.id AND ur.company_id = p.company_id
  );

-- 8.3 ADMIN: every permission
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r
CROSS JOIN permissions p
WHERE lower(r.name) = 'admin'
  AND NOT EXISTS (
      SELECT 1 FROM role_permissions rp WHERE rp.role_id = r.id AND rp.permission_id = p.id
  );

-- 8.4 MANAGER / ACCOUNTANT / VIEWER: starter permission sets
INSERT INTO role_permissions (role_id, permission_id)
SELECT r.id, p.id
FROM roles r
CROSS JOIN permissions p
WHERE (lower(r.name) = 'manager'
       AND p.module IN ('dashboard','products','categories','brands','customers','suppliers',
                        'sales','purchases','quotations','purchase_orders','proforma_invoices',
                        'stock','warehouses')
       AND p.action <> 'delete')
   OR (lower(r.name) = 'accountant'
       AND p.module IN ('dashboard','sales','purchases','quotations','proforma_invoices',
                        'payments_received','payments_made','reports','audit_logs'))
   OR (lower(r.name) = 'viewer'
       AND p.action IN ('read', 'dashboard'))
ON CONFLICT DO NOTHING;

-- ==================================================================
-- from 009_billing_module.sql
-- ==================================================================
-- ============================================================
-- 009_billing_module.sql - Billing module backend
--
-- Adds:
--   1. document_series         - configurable per-company numbering
--   2. Atomic preview / allocate / reset RPCs
--   3. transactions.company_snapshot + payment_allocations
--   4. company_settings.document_terms + payment_methods
--
-- Numbering rules enforced here rather than in the browser:
--   * opening a form only previews a number (no write, no increment)
--   * a number is allocated exactly once, inside allocate_document_number,
--     under a row lock on the series, so concurrent saves cannot collide
--   * the allocated number is kept when the document is edited
--   * a number that already exists on a document is never handed out twice
-- ============================================================

-- ============================================================
-- 1. DOCUMENT_SERIES
-- ============================================================
CREATE TABLE IF NOT EXISTS document_series (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    doc_type TEXT NOT NULL CHECK (doc_type IN
        ('sale', 'purchase', 'quotation', 'purchase_order', 'proforma_invoice')),
    prefix TEXT NOT NULL DEFAULT 'PI/',
    financial_year TEXT NOT NULL DEFAULT '',
    auto_fy BOOLEAN NOT NULL DEFAULT TRUE,
    start_number INT NOT NULL DEFAULT 1,
    padding INT NOT NULL DEFAULT 4,
    suffix TEXT NOT NULL DEFAULT '',
    next_number INT NOT NULL DEFAULT 1,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_document_series_company_type UNIQUE (company_id, doc_type),
    CONSTRAINT chk_document_series_padding CHECK (padding BETWEEN 1 AND 10),
    CONSTRAINT chk_document_series_start CHECK (start_number >= 1),
    CONSTRAINT chk_document_series_next CHECK (next_number >= 1)
);

CREATE INDEX IF NOT EXISTS idx_document_series_company
    ON document_series(company_id);

DROP TRIGGER IF EXISTS trg_document_series_updated_at ON document_series;
CREATE TRIGGER trg_document_series_updated_at
    BEFORE UPDATE ON document_series
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ============================================================
-- 2. ROW LEVEL SECURITY
--    Reading the series is harmless for any company member, but
--    editing it is an administrator action.
-- ============================================================
ALTER TABLE document_series ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "document_series_select_own" ON document_series;
DROP POLICY IF EXISTS "document_series_select_own" ON document_series;
CREATE POLICY "document_series_select_own" ON document_series
    FOR SELECT USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "document_series_insert_own" ON document_series;
DROP POLICY IF EXISTS "document_series_insert_own" ON document_series;
CREATE POLICY "document_series_insert_own" ON document_series
    FOR INSERT WITH CHECK (
        company_id = public.user_company_id()
        AND (public.user_is_admin() OR public.user_has_permission('settings', 'update'))
    );

DROP POLICY IF EXISTS "document_series_update_own" ON document_series;
DROP POLICY IF EXISTS "document_series_update_own" ON document_series;
CREATE POLICY "document_series_update_own" ON document_series
    FOR UPDATE USING (
        company_id = public.user_company_id()
        AND (public.user_is_admin() OR public.user_has_permission('settings', 'update'))
    )
    WITH CHECK (
        company_id = public.user_company_id()
        AND (public.user_is_admin() OR public.user_has_permission('settings', 'update'))
    );

DROP POLICY IF EXISTS "document_series_delete_own" ON document_series;
DROP POLICY IF EXISTS "document_series_delete_own" ON document_series;
CREATE POLICY "document_series_delete_own" ON document_series
    FOR DELETE USING (
        company_id = public.user_company_id()
        AND (public.user_is_admin() OR public.user_has_permission('settings', 'update'))
    );

-- ============================================================
-- 3. HELPERS
-- ============================================================

-- Indian financial year, 1 April – 31 March.
-- April 2026 .. March 2027 -> '26-27'
CREATE OR REPLACE FUNCTION public.billing_fiscal_year(p_date DATE DEFAULT CURRENT_DATE)
RETURNS TEXT AS $$
DECLARE
    v_date DATE := COALESCE(p_date, CURRENT_DATE);
BEGIN
    IF EXTRACT(MONTH FROM v_date) >= 4 THEN
        RETURN TO_CHAR(v_date, 'YY') || '-' || TO_CHAR(v_date + INTERVAL '1 year', 'YY');
    END IF;
    RETURN TO_CHAR(v_date - INTERVAL '1 year', 'YY') || '-' || TO_CHAR(v_date, 'YY');
END;
$$ LANGUAGE plpgsql IMMUTABLE;

CREATE OR REPLACE FUNCTION public.billing_format_number(
    p_prefix TEXT,
    p_fiscal_year TEXT,
    p_sequence INT,
    p_padding INT,
    p_suffix TEXT DEFAULT ''
) RETURNS TEXT AS $$
    SELECT COALESCE(p_prefix, '')
        || COALESCE(NULLIF(p_fiscal_year, ''), '')
        || '/'
        || LPAD(GREATEST(COALESCE(p_sequence, 1), 0)::TEXT,
                GREATEST(COALESCE(p_padding, 4), 1), '0')
        || COALESCE(p_suffix, '');
$$ LANGUAGE sql IMMUTABLE;

-- A document number is only ever issued to somebody who belongs to the
-- company. Without this any signed-in user could read another tenant's
-- next invoice number by passing their company id.
CREATE OR REPLACE FUNCTION public.billing_assert_company(p_company_id UUID)
RETURNS VOID AS $$
DECLARE
    v_company UUID;
BEGIN
    SELECT company_id INTO v_company FROM profiles WHERE id = auth.uid();
    IF v_company IS NULL OR v_company <> p_company_id THEN
        RAISE EXCEPTION 'Not authorized for this company';
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION public.billing_assert_settings_manager()
RETURNS VOID AS $$
BEGIN
    IF NOT (public.user_is_admin() OR public.user_has_permission('settings', 'update')) THEN
        RAISE EXCEPTION 'You need the settings:update permission to change numbering';
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION public.billing_default_prefix(p_doc_type TEXT)
RETURNS TEXT AS $$
    SELECT CASE p_doc_type
        WHEN 'sale' THEN 'INV/'
        WHEN 'purchase' THEN 'PUR/'
        WHEN 'quotation' THEN 'QUO/'
        WHEN 'purchase_order' THEN 'PO/'
        ELSE 'PI/'
    END;
$$ LANGUAGE sql IMMUTABLE;

-- Lazily creates the row for a company/document-type. Never consumes a
-- number, so calling it from a preview is safe.
CREATE OR REPLACE FUNCTION public.billing_ensure_series(p_company_id UUID, p_doc_type TEXT)
RETURNS document_series AS $$
DECLARE
    v_series document_series;
BEGIN
    SELECT * INTO v_series
    FROM document_series
    WHERE company_id = p_company_id AND doc_type = p_doc_type;

    IF FOUND THEN
        RETURN v_series;
    END IF;

    BEGIN
        INSERT INTO document_series
            (company_id, doc_type, prefix, financial_year, start_number, padding, next_number)
        VALUES
            (p_company_id, p_doc_type, billing_default_prefix(p_doc_type),
             billing_fiscal_year(CURRENT_DATE), 1, 4, 1)
        RETURNING * INTO v_series;
    EXCEPTION WHEN unique_violation THEN
        -- Another session created it between the SELECT and the INSERT.
        SELECT * INTO v_series
        FROM document_series
        WHERE company_id = p_company_id AND doc_type = p_doc_type;
    END;

    RETURN v_series;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 4. preview_document_number  (read only - never increments)
-- ============================================================
CREATE OR REPLACE FUNCTION public.preview_document_number(
    p_company_id UUID,
    p_doc_type TEXT,
    p_doc_date DATE DEFAULT NULL
) RETURNS TEXT AS $$
DECLARE
    v_series document_series;
    v_date DATE := COALESCE(p_doc_date, CURRENT_DATE);
    v_fy TEXT;
    v_next INT;
BEGIN
    PERFORM public.billing_assert_company(p_company_id);
    v_series := public.billing_ensure_series(p_company_id, p_doc_type);

    IF v_series.auto_fy THEN
        v_fy := public.billing_fiscal_year(v_date);
        -- A preview for a document dated in the next financial year shows
        -- the series as it will be after the automatic rollover, without
        -- writing anything.
        IF COALESCE(NULLIF(v_series.financial_year, ''), v_fy) <> v_fy THEN
            v_next := COALESCE(v_series.start_number, 1);
        ELSE
            v_next := v_series.next_number;
        END IF;
    ELSE
        v_fy := COALESCE(NULLIF(v_series.financial_year, ''),
                         public.billing_fiscal_year(v_date));
        v_next := v_series.next_number;
    END IF;

    RETURN public.billing_format_number(
        v_series.prefix, v_fy, v_next, v_series.padding, v_series.suffix
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 5. allocate_document_number  (the only place a number is minted)
--
-- Row lock on the series serialises callers, so two users saving at
-- the same instant get 0001 and 0002, never 0001 twice. The
-- EXISTS guard skips over any number already printed on an old
-- document so a reconfigured series cannot collide with history.
-- ============================================================
CREATE OR REPLACE FUNCTION public.allocate_document_number(
    p_company_id UUID,
    p_doc_type TEXT,
    p_doc_date DATE DEFAULT NULL
) RETURNS TEXT AS $$
DECLARE
    v_series document_series%ROWTYPE;
    v_date DATE := COALESCE(p_doc_date, CURRENT_DATE);
    v_fy TEXT;
    v_next INT;
    v_number TEXT;
    v_guard INT := 0;
BEGIN
    PERFORM public.billing_assert_company(p_company_id);
    PERFORM public.billing_ensure_series(p_company_id, p_doc_type);

    SELECT * INTO v_series
    FROM document_series
    WHERE company_id = p_company_id AND doc_type = p_doc_type
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Numbering series not configured for %', p_doc_type;
    END IF;

    IF NOT v_series.enabled THEN
        RAISE EXCEPTION 'Document numbering is disabled for % - enable it in Settings', p_doc_type;
    END IF;

    v_fy := public.billing_fiscal_year(v_date);

    IF v_series.auto_fy THEN
        IF COALESCE(NULLIF(v_series.financial_year, ''), v_fy) <> v_fy THEN
            -- New financial year: restart from the configured start number.
            v_next := COALESCE(v_series.start_number, 1);
        ELSE
            v_next := v_series.next_number;
        END IF;
    ELSE
        v_fy := COALESCE(NULLIF(v_series.financial_year, ''), v_fy);
        v_next := v_series.next_number;
    END IF;

    LOOP
        v_number := public.billing_format_number(
            v_series.prefix, v_fy, v_next, v_series.padding, v_series.suffix
        );

        EXIT WHEN NOT EXISTS (
            SELECT 1 FROM transactions
            WHERE company_id = p_company_id
              AND type = p_doc_type
              AND document_number = v_number
        );

        v_next := v_next + 1;
        v_guard := v_guard + 1;
        IF v_guard > 100000 THEN
            RAISE EXCEPTION 'Could not find a free document number for %', p_doc_type;
        END IF;
    END LOOP;

    UPDATE document_series
    SET next_number = v_next + 1,
        financial_year = v_fy,
        updated_at = now()
    WHERE id = v_series.id;

    RETURN v_number;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 6. reset_document_series  (manual restart / new financial year)
-- ============================================================
CREATE OR REPLACE FUNCTION public.reset_document_series(
    p_company_id UUID,
    p_doc_type TEXT,
    p_next_number INT DEFAULT NULL,
    p_financial_year TEXT DEFAULT NULL
) RETURNS INT AS $$
DECLARE
    v_series document_series;
    v_next INT;
BEGIN
    PERFORM public.billing_assert_company(p_company_id);
    PERFORM public.billing_assert_settings_manager();
    PERFORM public.billing_ensure_series(p_company_id, p_doc_type);

    SELECT * INTO v_series
    FROM document_series
    WHERE company_id = p_company_id AND doc_type = p_doc_type
    FOR UPDATE;

    v_next := COALESCE(p_next_number, v_series.start_number, 1);

    UPDATE document_series
    SET next_number = GREATEST(v_next, 1),
        financial_year = COALESCE(
            NULLIF(p_financial_year, ''),
            billing_fiscal_year(CURRENT_DATE)
        ),
        updated_at = now()
    WHERE id = v_series.id
    RETURNING next_number INTO v_next;

    RETURN v_next;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 7. next_document_number - kept for existing call sites, now
--    delegating to the configured series so every document type
--    uses the same atomic allocator.
-- ============================================================
CREATE OR REPLACE FUNCTION public.next_document_number(
    p_company_id UUID,
    p_type TEXT
) RETURNS TEXT AS $$
BEGIN
    RETURN public.allocate_document_number(p_company_id, p_type, CURRENT_DATE);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================================
-- 8. GRANTS
-- ============================================================
GRANT EXECUTE ON FUNCTION public.billing_fiscal_year(DATE) TO authenticated;
GRANT EXECUTE ON FUNCTION public.billing_format_number(TEXT, TEXT, INT, INT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.billing_default_prefix(TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.billing_assert_company(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.billing_assert_settings_manager() TO authenticated;
GRANT EXECUTE ON FUNCTION public.billing_ensure_series(UUID, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.preview_document_number(UUID, TEXT, DATE) TO authenticated;
GRANT EXECUTE ON FUNCTION public.allocate_document_number(UUID, TEXT, DATE) TO authenticated;
GRANT EXECUTE ON FUNCTION public.reset_document_series(UUID, TEXT, INT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION public.next_document_number(UUID, TEXT) TO authenticated;

-- ============================================================
-- 9. TRANSACTIONS - document snapshot + payment intent
-- ============================================================

-- Company details at the moment the document was issued, so editing the
-- company profile later cannot rewrite history on old invoices.
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS company_snapshot JSONB;

-- Payment rows are an intention on a draft/proforma and a record of the
-- allocation on a posted invoice. Stored per document so reprinting never
-- re-creates a payment.
ALTER TABLE transactions ADD COLUMN IF NOT EXISTS payment_allocations JSONB
    NOT NULL DEFAULT '[]'::jsonb;

-- ============================================================
-- 10. COMPANY_SETTINGS - terms defaults + payment method config
-- ============================================================
ALTER TABLE company_settings ADD COLUMN IF NOT EXISTS document_terms JSONB
    NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE company_settings ADD COLUMN IF NOT EXISTS payment_methods JSONB
    NOT NULL DEFAULT '[]'::jsonb;

-- ==================================================================
-- from 010_stock_statement_import.sql
-- ==================================================================
-- ============================================================
-- 010_stock_statement_import.sql – Advanced Excel import for the
--                       stock statement
--
-- The stock statement reads its column list straight from the Excel
-- header row, so the schema has to store two things the product table
-- cannot: which columns a file supplied, and the raw cell values of
-- every row that does not map onto a product column (unit, gst, sl no,
-- or any other header the user invents).
-- ============================================================

-- ============================================================
-- 1. STOCK_STATEMENT_IMPORTS  (one row per uploaded file)
-- ============================================================
CREATE TABLE IF NOT EXISTS stock_statement_imports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    file_name TEXT,
    columns JSONB NOT NULL DEFAULT '[]'::jsonb,
    row_count INT NOT NULL DEFAULT 0,
    created_by UUID REFERENCES profiles(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_stock_statement_imports_company
    ON stock_statement_imports(company_id);

-- ============================================================
-- 2. STOCK_STATEMENT_ROWS  (one row per product, latest file wins)
-- ============================================================
CREATE TABLE IF NOT EXISTS stock_statement_rows (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
    import_id UUID REFERENCES stock_statement_imports(id) ON DELETE SET NULL,
    product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    data JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_stock_statement_rows_company_product UNIQUE(company_id, product_id)
);

CREATE INDEX IF NOT EXISTS idx_stock_statement_rows_company
    ON stock_statement_rows(company_id);
CREATE INDEX IF NOT EXISTS idx_stock_statement_rows_product
    ON stock_statement_rows(product_id);

-- ============================================================
-- 3. ROW LEVEL SECURITY
-- ============================================================
ALTER TABLE stock_statement_imports ENABLE ROW LEVEL SECURITY;
ALTER TABLE stock_statement_rows ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "stock_statement_imports_select_own" ON stock_statement_imports;
CREATE POLICY "stock_statement_imports_select_own" ON stock_statement_imports
    FOR SELECT USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "stock_statement_imports_insert_own" ON stock_statement_imports;
CREATE POLICY "stock_statement_imports_insert_own" ON stock_statement_imports
    FOR INSERT WITH CHECK (
        company_id = public.user_company_id()
    );

DROP POLICY IF EXISTS "stock_statement_imports_update_own" ON stock_statement_imports;
CREATE POLICY "stock_statement_imports_update_own" ON stock_statement_imports
    FOR UPDATE USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "stock_statement_imports_delete_own" ON stock_statement_imports;
CREATE POLICY "stock_statement_imports_delete_own" ON stock_statement_imports
    FOR DELETE USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "stock_statement_rows_select_own" ON stock_statement_rows;
CREATE POLICY "stock_statement_rows_select_own" ON stock_statement_rows
    FOR SELECT USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "stock_statement_rows_insert_own" ON stock_statement_rows;
CREATE POLICY "stock_statement_rows_insert_own" ON stock_statement_rows
    FOR INSERT WITH CHECK (
        company_id = public.user_company_id()
    );

DROP POLICY IF EXISTS "stock_statement_rows_update_own" ON stock_statement_rows;
CREATE POLICY "stock_statement_rows_update_own" ON stock_statement_rows
    FOR UPDATE USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

DROP POLICY IF EXISTS "stock_statement_rows_delete_own" ON stock_statement_rows;
CREATE POLICY "stock_statement_rows_delete_own" ON stock_statement_rows
    FOR DELETE USING (
        company_id = public.user_company_id()
        OR public.user_is_admin()
    );

-- ==================================================================
-- from 011_block_public_signup.sql
-- ==================================================================
-- ============================================================
-- 011_block_public_signup.sql - Internal staff accounts only
--
-- BSP Inventory is internal company software: every account is
-- created by an administrator (Users -> Add User) or seeded with
-- supabase/seed/admin_user.sql. Self-service registration has been
-- removed from the UI, but the UI alone does not stop anyone holding
-- the public anon key from calling supabase.auth.signUp() directly,
-- so the guard lives in the database - the one place every new
-- auth.users row has to pass through.
--
-- The on_auth_user_created trigger (005, redefined by 007) now:
--
--   1. REJECTS any signup whose raw_user_meta_data does not carry
--      invited_by_admin = true. The RAISE happens inside an AFTER
--      INSERT trigger, so the whole insert rolls back and GoTrue
--      reports the signup as failed - no auth user, no profile.
--
--   2. For an invited user, provisions the complete profile -
--      company_id, role, department, contact - from the invitation
--      metadata. Previously the trigger always inserted a bare
--      'viewer' profile first and the application's own insert then
--      collided with it (ON CONFLICT), so the role and company an
--      admin picked were silently dropped.
--
-- Client side of this change:
--   * src/modules/users/UserListPage.tsx sends invited_by_admin plus
--     the profile fields in options.data and no longer inserts into
--     profiles itself.
--   * src/pages/SignupPage.tsx (self-service signup) was deleted and
--     the /signup route removed.
--
-- Existing auth.users rows are untouched: the trigger only fires on
-- INSERT. Additive only; safe to re-run (CREATE OR REPLACE).
-- ============================================================

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
DECLARE
    v_invited    BOOLEAN := false;
    v_company_id UUID;
    v_full_name  TEXT;
    v_role       TEXT;
    v_contact    TEXT;
    v_department TEXT;
BEGIN
    -- raw_user_meta_data is the only metadata bucket a browser can set
    -- through supabase.auth.signUp({ options: { data: {...} } }).
    v_invited := lower(coalesce(NEW.raw_user_meta_data ->> 'invited_by_admin', ''))
                 IN ('true', '1', 'yes');

    IF NOT v_invited THEN
        RAISE EXCEPTION
            'Public sign-up is disabled. Ask an administrator to create your account.';
    END IF;

    v_full_name  := NULLIF(trim(NEW.raw_user_meta_data ->> 'full_name'), '');
    v_role       := COALESCE(NULLIF(trim(NEW.raw_user_meta_data ->> 'role'), ''), 'viewer');
    v_contact    := NULLIF(trim(NEW.raw_user_meta_data ->> 'contact'), '');
    v_department := NULLIF(trim(NEW.raw_user_meta_data ->> 'department'), '');

    -- Optional: attach the invited user to an existing company.
    BEGIN
        v_company_id := NULLIF(trim(NEW.raw_user_meta_data ->> 'company_id'), '')::UUID;
    EXCEPTION WHEN others THEN
        v_company_id := NULL;
    END;

    IF v_company_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM companies WHERE id = v_company_id) THEN
        v_company_id := NULL;
    END IF;

    INSERT INTO public.profiles (
        id, company_id, email, full_name, contact, department, role, is_active
    )
    VALUES (
        NEW.id,
        v_company_id,
        NEW.email,
        v_full_name,
        v_contact,
        v_department,
        v_role,
        true
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Re-point the existing trigger at the updated function body.
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

COMMIT;
